'use strict';
(function(root){
// Rendering-only simulations never publish damage, healing, loot or save data.
class RaidEffects{
constructor(D){this.D=D;this.active=[];this.seen=new Set();this.room=null;this.last=0;this.painters=new WeakMap();}
reset(room){this.active=[];this.seen.clear();this.room=room;this.last=0;}
update(session){const s=session?.state;if(!s)return;const key=session.room+':'+(s.runId||'practice');if(this.room!==key)this.reset(key);for(const e of s.effects||[]){if(!Number.isInteger(e.slot)||!e.owner)continue;const id=e.owner+':'+e.slot+':'+e.at;if(this.seen.has(id))continue;this.seen.add(id);const actor=s.players.find(p=>p.id===e.owner),skill=this.D.skills.find(d=>d.heroId===actor?.hero&&d.cell===actor?.cell&&d.slot===e.slot);if(!actor||!skill)continue;const sc=root.RPG_PREVIEW.scene(this.D,skill);sc.hero={x:actor.x,y:actor.y};sc.enemies=[{x:400,y:190,model:this.D.regions[7].bosses[0],height:130}];sc.count=1;const sim=root.RPG_PREVIEW.createSimulation(sc);if(!sim)continue;const g=sim.g;g.time=0;g.c.heroId=actor.hero;g.c.casting=0;g.events=[];const ok=g.castSkill(skill.slot,true);if(!ok){const d=g.skillSpec(skill.slot),target=g.c.enemies[0],event={effectType:d.effectType,heroId:actor.hero,cell:actor.cell,slot:skill.slot,name:skill.name,fx:skill.fx,from:{...sc.hero},x:400,y:190,ultimate:skill.slot===3};const ctx={combat:g.c,d,target,point:{x:400,y:190},origin:{...sc.hero},attack:g.stats().attack,multi:1,event};for(const a of skill.actions)g.performSkillAction(a,ctx);g.emit('skill',event);}
root.RPG_VFX?.preload(actor.hero,actor.cell);this.active=this.active.filter(v=>v.owner!==e.owner||v.slot!==e.slot);this.active.push({owner:e.owner,slot:e.slot,skill,g,age:0,life:actor.hero===2&&skill.actions[0]?.kind==='permafrost'?9.5:actor.hero===7&&actor.cell===5?14.5:skill.actions[0]?.kind==='half-dragon'?12.5:/summon|pet|spirit|fusion|king|merchant/.test(skill.actions.map(a=>a.op).join(' '))||[5,11].includes(actor.hero)?7:3.2});if(this.active.length>16)this.active.shift();}if(this.seen.size>256)this.seen=new Set([...this.seen].slice(-128));}
step(dt){dt=Math.min(.1,Math.max(0,dt));for(const v of this.active){v.age+=dt;const g=v.g;g.time+=dt;g.tickSkills(dt);g.tickTechniques(dt);if(g.c.formTime>0)g.c.formTime=Math.max(0,g.c.formTime-dt);}this.active=this.active.filter(v=>v.age<v.life);}
motion(owner){const v=[...this.active].reverse().find(v=>v.owner===owner);if(!v)return null;const c=v.g.c;const motion=c.mage?.motion||c.rogue?.motion||c.sword?.motion||c.archer?.motion||c.idol?.motion||c.priest?.motion||c.merchant?.motion||c.gunner?.motion||c.knight?.motion||c.metal?.motion||c.cheonbin?.motion||c.warrior?.motion||{profile:v.skill.actions[0]?.profile||'prayer',start:0,duration:.7};const beast=[...this.active].reverse().find(a=>a.owner===owner&&a.g.s.active===7&&a.g.c.formTime>0);if(beast)return {...motion,beastForm:{row:beast.g.c.cheonbin?.primal?2:beast.g.c.form==='bear'?1:0}};return this.active.some(a=>a.owner===owner&&a.g.c.knight?.metamorph>0)?{...motion,knightForm:true}:motion;}
paint(p,drawSprite){let art=this.painters.get(p);if(!art){art=new Proxy(p,{get:(target,key)=>{if(key==='fillText'||key==='strokeText')return()=>{};const value=Reflect.get(target,key,target);return typeof value==='function'?value.bind(target):value;},set:(target,key,value)=>Reflect.set(target,key,value,target)});this.painters.set(p,art);}p=art;for(const v of this.active){const g=v.g,c=g.c;p.save();const isStateOnly=v.age>2.3;
root.RPG_MAGE_FX?.ground(p,g,g.time);root.RPG_SWORD_FX?.ground(p,g,g.time);root.RPG_ARCHER_FX?.ground(p,g,g.time);root.RPG_KNIGHT_FX?.ground(p,g,g.time);root.RPG_MERCHANT_FX?.ground(p,g,g.time);root.RPG_GUNNER_FX?.ground(p,g,g.time);
root.RPG_PREVIEW.drawObjects(p,this.D,v.skill,{sim:g},g.time,drawSprite,false);
// drawObjects dispatches bespoke impact events; ordinary cast events are drawn once here.
if(!isStateOnly)for(const f of g.events){if(f.type==='skill'&&g.time-f.time<2.4)root.RPG_SKILL_FX.draw(p,f,g.time-f.time,this.D);}
p.restore();}}
}
if(typeof module!=='undefined')module.exports=RaidEffects;root.RPG_RAID_EFFECTS=RaidEffects;
})(typeof window!=='undefined'?window:globalThis);
